#include "gfx.h"
#include "fonts.h"  // generated by CMake from vendor/fonts

#include <cmath>

namespace G = ImGui;

namespace gfx {

namespace {
ImGui_Context* g_ctx = nullptr;
ImGui_DrawList* g_dl = nullptr;
ImGui_Font *g_font = nullptr, *g_bold = nullptr;
double g_ox = 0, g_oy = 0;

}  // namespace

void attach_fonts(ImGui_Context* ctx) {
  g_font = G::CreateFontFromMem((const char*)kFontUi, int(sizeof kFontUi));
  g_bold = G::CreateFontFromMem((const char*)kFontBold, int(sizeof kFontBold));
  G::Attach(ctx, (ImGui_Resource*)g_font);
  G::Attach(ctx, (ImGui_Resource*)g_bold);
}

void begin(ImGui_Context* ctx) {
  g_ctx = ctx;
  g_dl = G::GetWindowDrawList(ctx);
  G::GetCursorScreenPos(ctx, &g_ox, &g_oy);
}

double ox() { return g_ox; }
double oy() { return g_oy; }

void fill(double x, double y, double w, double h, int col) {
  G::DrawList_AddRectFilled(g_dl, g_ox + x, g_oy + y, g_ox + x + w, g_oy + y + h, col);
}

void frame(double x, double y, double w, double h, int col) {
  fill(x, y, w, 1, col);
  fill(x, y + h - 1, w, 1, col);
  fill(x, y, 1, h, col);
  fill(x + w - 1, y, 1, h, col);
}

void line(double x0, double y0, double x1, double y1, int col, double thickness) {
  G::DrawList_AddLine(g_dl, g_ox + x0, g_oy + y0, g_ox + x1, g_oy + y1, col, thickness);
}

void round_box(double x, double y, double w, double h, double r, int fill_col, int line_col) {
  G::DrawList_AddRectFilled(g_dl, g_ox + x, g_oy + y, g_ox + x + w, g_oy + y + h, fill_col, r);
  G::DrawList_AddRect(g_dl, g_ox + x + 0.5, g_oy + y + 0.5, g_ox + x + w - 0.5, g_oy + y + h - 0.5, line_col, r, 0, 1);
}

void tri(const double* x, const double* y, int fill_col, int line_col) {
  G::DrawList_AddTriangleFilled(g_dl, g_ox + x[0], g_oy + y[0], g_ox + x[1], g_oy + y[1], g_ox + x[2], g_oy + y[2], fill_col);
  G::DrawList_AddTriangle(g_dl, g_ox + x[0], g_oy + y[0], g_ox + x[1], g_oy + y[1], g_ox + x[2], g_oy + y[2], line_col, 1);
}

ImGui_Font* ui_font() { return g_font; }

void text_in(double x, double y, double w, double h, const std::string& s, bool right, int col) {
  G::PushFont(g_ctx, g_font, kFontSize);
  double tw = 0, th = 0;
  G::CalcTextSize(g_ctx, s.c_str(), &tw, &th);
  G::DrawList_PushClipRect(g_dl, g_ox + x, g_oy + y, g_ox + x + w, g_oy + y + h, true);
  G::DrawList_AddText(g_dl, g_ox + (right ? std::floor(x + w - tw) : x), g_oy + std::floor(y + (h - th) / 2), col, s.c_str());
  G::DrawList_PopClipRect(g_dl);
  G::PopFont(g_ctx);
}

void text_centered(double x, double y, double w, double h, const std::string& s, int col, bool bold) {
  G::PushFont(g_ctx, bold ? g_bold : g_font, kFontSize);
  double tw = 0, th = 0;
  G::CalcTextSize(g_ctx, s.c_str(), &tw, &th);
  G::DrawList_PushClipRect(g_dl, g_ox + x, g_oy + y, g_ox + x + w, g_oy + y + h, true);
  G::DrawList_AddText(g_dl, g_ox + std::floor(x + (w - tw) / 2), g_oy + std::floor(y + (h - th) / 2), col, s.c_str());
  G::DrawList_PopClipRect(g_dl);
  G::PopFont(g_ctx);
}

}  // namespace gfx
